class Circle implements Shape {
    // package-private so the static clone (added to this same class by Soot) can read it
    final double radius;

    Circle(double radius) {
        this.radius = radius;
    }

    public double area() {
        return 3.14159265358979 * radius * radius;
    }

    public String describe() {
        return "Circle(r=" + radius + ")";
    }

    // ---------------------------------------------------------------
    // Static clones generated by MonomorphizationTransformer.
    // In the real optimizer these are injected into this class body
    // via SootClass.addMethod(), so they can access private fields.
    // We place them here to match that: same access scope, same class.
    // ---------------------------------------------------------------

    static double area$mono$Circle(Circle self) {
        return 3.14159265358979 * self.radius * self.radius;
    }

    static String describe$mono$Circle(Circle self) {
        return "Circle(r=" + self.radius + ")";
    }
}
